import api from '../utils/api';

const DUMMY_USER = {
  _id: 'mock-user-123',
  name: 'Demo User',
  email: 'user@example.com',
  role: 'customer'
};

export const authService = {
  async login(payload) {
    try {
      const { data } = await api.post('/auth/customer/login', payload);
      return data.data;
    } catch (error) {
      console.warn('Backend offline, using mock login');
      return { 
        user: { ...DUMMY_USER, email: payload.email, name: payload.email.split('@')[0] }, 
        token: 'mock-token' 
      };
    }
  },
  async register(payload) {
    try {
      const { data } = await api.post('/auth/customer/register', payload);
      return data.data;
    } catch (error) {
      console.warn('Backend offline, using mock registration');
      return { 
        user: { ...DUMMY_USER, name: payload.name, email: payload.email }, 
        token: 'mock-token' 
      };
    }
  },
  async forgotPassword(email) {
    try {
      const { data } = await api.post('/auth/customer/forgot-password', { email });
      return data;
    } catch (error) {
      return { message: 'Password reset link sent to your email (Mock)' };
    }
  },
  async resetPassword(token, password) {
    try {
      const { data } = await api.patch(`/auth/customer/reset-password/${token}`, { password });
      return data.data;
    } catch (error) {
      return { user: DUMMY_USER };
    }
  },
  async me() {
    try {
      const { data } = await api.get('/auth/customer/me');
      return data.data.user;
    } catch (error) {
      // Return null so AuthContext knows we are logged out if backend is down
      // unless we want to stay "logged in" with dummy data
      return null;
    }
  },
  async logout() {
    try {
      await api.post('/auth/customer/logout');
    } catch (error) {
      // Local logout is usually handled by clearing storage in AuthContext
    }
  },
  async updatePassword(currentPassword, newPassword) {
    try {
      const { data } = await api.patch('/auth/customer/update-password', { currentPassword, newPassword });
      return data.data;
    } catch (error) {
      return { user: DUMMY_USER };
    }
  }
};
